var n=`0945-yakitori`;var a=`world-0945`;var s=`JP`;var t=`east-asia`;var r=4;var o=63;var g={en:`Yakitori`,ua:`Якіторі`};var h={en:`Yakitori is a Japan dish made with chicken thigh, light soy sauce, green onion. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Якіторі, страва кухні країни Японія. Основні складники: куряче стегно, світлий соєвий соус, зелена цибуля. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var l=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 30 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 30 хвилин.`,t:[`marinating`],m:30,i:[[`chicken-thigh`,750,`g`],[`light-soy-sauce`,70,`ml`],[`mirin`,65,`ml`],[`sake`,50,`ml`],[`white-granulated-sugar`,30,`g`]]},{en:`Thread the prepared pieces onto skewers, leaving small gaps to ensure even cooking.`,ua:`Нанизайте підготовлені шматочки на шампури чи шпажки, залишаючи невеликі проміжки для рівномірного приготування.`,t:[`threading-skewers`],m:14,i:[[`green-onion`,150,`g`]]},{en:`Grill over medium-high heat for about 16 minutes, turning regularly until charred outside and safely cooked inside.`,ua:`Смажте на грилі на середньо-сильному жарі приблизно 16 хвилин, регулярно перевертаючи до рум’яної скоринки та повної готовності всередині.`,t:[`grilling`],m:16,i:[[`canola-oil`,25,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`shichimi-togarashi`,5,`g`]]}];var u={slug:n,id:a,country:`JP`,region:t,servings:4,minutes:63,title:g,text:h,steps:l};export{s as country,u as default,a as id,o as minutes,t as region,r as servings,n as slug,l as steps,h as text,g as title};